(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.DojoSubscriptionUI=api;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
 const price='R$ 11,99',terms='2026-11-11.plus.1';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=s=>s?new Date(s).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):'';
 function markup(data={},logged=false){
  const active=data.active===true,order=data.order,available=data.available===true&&data.plan?.priceCents===1199;
  const pending=order&&['creating','pending'].includes(order.state);
  const cancellable=order&&!order.renewalCancelled&&(order.hasSubscription||order.hasCheckout);
  return `<section class="animate-in subscription-page"><button class="back-link" data-view="account">← Minha conta</button><span class="eyebrow">ÁREA DO RESPONSÁVEL</span><h1>San Dojo Plus</h1><p class="intro">Mais liberdade para estudar, no ritmo do aluno.</p>${data.mode==='sandbox'?'<p class="subscription-test">AMBIENTE DE TESTE · sem cobrança real · exclusivo do administrador</p>':''}<div class="subscription-layout"><article class="info-panel subscription-plan"><span class="subscription-symbol" aria-hidden="true">∞</span><h2>Energia ilimitada</h2><p class="subscription-price"><strong>${price}</strong> / mês</p><p>Assinatura mensal para uma conta de aluno, com renovação automática no cartão.</p><ul><li>Faça atividades sem gastar energia enquanto o plano estiver ativo.</li><li>Seu progresso, suas KC e sua faixa ilustrativa seguem as regras das atividades.</li><li>Cancele a renovação nesta página. O acesso continua até o fim do período pago.</li></ul>${active?`<p class="subscription-active">✓ Energia ilimitada ativa até ${date(data.periodEnd)}.</p>${order?.renewalCancelled?'<p>A renovação foi cancelada. Não haverá novas cobranças dessa assinatura.</p>':''}`:pending?'<p class="learning-callout">Contratação em andamento. Atualize a situação após concluir o pagamento. Não é necessário contratar novamente.</p>':!available?'<p class="learning-callout">Assinaturas em preparação. A versão gratuita continua disponível.</p>':''}${!logged?'<button class="primary" data-view="account">Entrar como responsável →</button>':available&&!active&&(!order||order.renewalCancelled||pending)?`<form id="subscription-start"><label class="subscription-check"><input type="checkbox" name="confirm" required> Sou responsável adulto e concordo com a cobrança de ${price} por mês, renovada automaticamente até eu cancelar. Li os <a href="termos.html#assinatura" target="_blank" rel="noopener">termos da assinatura</a>.</label><button class="primary" type="submit">${pending?'Continuar contratação':'Continuar no Asaas'} →</button><small>Os dados do cartão são preenchidos no Asaas. A energia é liberada após a confirmação do pagamento.</small></form>`:''}<div class="subscription-actions">${logged?'<button class="outline" data-subscription-refresh>Atualizar situação</button>':''}${logged&&cancellable?'<button class="text-button" data-subscription-cancel>Cancelar renovação ou contratação</button>':''}</div><p id="subscription-message" role="status">${esc(data.message||'')}</p><div id="subscription-cancel-confirm"></div></article><aside class="info-panel"><h2>Você escolhe como estudar</h2><p>A versão gratuita mantém 25 energias, com recarga de 5 a cada 30 minutos. As aulas e os desafios continuam disponíveis conforme seu progresso.</p><p>O plano Plus oferece energia ilimitada. Ele não compra aprovação, faixa ou graduação real.</p><p>Dúvidas, cancelamento ou reembolso: <a href="mailto:personalandrecordeiro@gmail.com?subject=Assinatura%20San%20Dojo">fale com André</a>.</p><h3>Últimas cobranças</h3>${data.payments?.length?`<ul class="subscription-payments">${data.payments.map(p=>`<li>${date(p.period_start)} · ${(p.amount_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}<br><small>${p.revoked?'Benefício suspenso ou pagamento não confirmado':['CONFIRMED','RECEIVED'].includes(p.status)?'Pagamento confirmado':'Aguardando confirmação'}</small></li>`).join('')}</ul>`:'<p>Nenhuma cobrança registrada nesta página.</p>'}</aside></div></section>`;
 }
 return {markup,terms,price};
});
